纯手搓其实也不复杂，下面的写法用减法省略了一个哈希表。 
  C++  Python        class     Solution     { 
public  : 
      bool     isAnagram  (  string     s  ,     string     t  )     { 
          if     (  s  .  length  ()     !=     t  .  length  ())     { 
              return     false  ; 
          } 
          vector  <  int  >     table  (  26  ,     0  ); 
          for     (  auto  &     ch  :     s  )     { 
              table  [  ch     -     'a'  ]  ++  ; 
          } 
          for     (  auto  &     ch  :     t  )     { 
              table  [  ch     -     'a'  ]  --  ; 
              if     (  table  [  ch     -     'a'  ]     <     0  )     { 
                  return     false  ; 
              } 
          } 
          return     true  ; 
      } 
}; 

      class     Solution  : 
    def     isAnagram  (  self  ,   s  ,   t  ): 
        if   len  (  s  )   !=   len  (  t  ):   return   False 
        table   =   [  0  ]   *   26 
        for   c   in   s  :   table  [  ord  (  c  )   -   ord  (  'a'  )]   +=   1 
        for   c   in   t  : 
            i   =   ord  (  c  )   -   ord  (  'a'  ) 
            table  [  i  ]   -=   1 
            if   table  [  i  ]   <   0  :   return   False 
        return   True 




时间复杂度： \(O(N)\)  
空间复杂度： \(O(N)\) ，如果确认字符都是字母，可以使用长为26的数组作为哈希表，空间复杂度就是 \(O(1)\)

  C++  Python        class     Solution     { 
    public  : 
      vector  <  vector  <  string  >>     groupAnagrams  (  vector  <  string  >     &  strs  )     { 
          unordered_map  <  string  ,     vector  <  string  >>     cnt  ; 
          for     (  const     string     &  word     :     strs  )     { 
              string     key     =     word  ; 
              sort  (  key  .  begin  (),     key  .  end  ()); 
              cnt  [  key  ].  push_back  (  word  ); 
          } 
          vector  <  vector  <  string  >>     res  ; 
          for     (  auto     &  [  key  ,     group  ]     :     cnt  ) 
              res  .  push_back  (  std  ::  move  (  group  )); 
          return     res  ; 
      } 
}; 

