class     Solution  : 
    def     longestConsecutive  (  self  ,   nums  :   List  [  int  ])   ->   int  : 
        st   =   set  (  nums  ) 
        res   =   0 
        for   num   in   st  : 
            if   num   -   1   not   in   st  :   # 只有当 num - 1 不在集合中时，才考虑以 num 开头的序列 
                k   =   1 
                while   (  num   +   k  )   in   st  : 
                    k   +=   1 
                res   =   max  (  res  ,   k  ) 
        return   res 




