  C++  Python        class     Solution     { 
    public  : 
      vector  <  vector  <  int  >>     threeSum  (  vector  <  int  >     &  nums  )     { 
          sort  (  nums  .  begin  (),     nums  .  end  ()); 
          int     n     =     nums  .  size  (); 
          vector  <  vector  <  int  >>     res  ; 
          for     (  int     left     =     0  ;     left     <     n     -     2  ;     ++  left  )     { 
              int     num     =     nums  [  left  ]; 
              if     (  left     >     0     &&     num     ==     nums  [  left     -     1  ]) 
                  continue  ; 

              int     mid     =     left     +     1  ,     right     =     n     -     1  ; 
              while     (  mid     <     right  )     { 
                  int     total     =     num     +     nums  [  mid  ]     +     nums  [  right  ]; 
                  if     (  total     <     0  ) 
                      ++  mid  ; 
                  else     if     (  total     >     0  ) 
                      --  right  ; 
                  else     { 
                      res  .  push_back  ({  num  ,     nums  [  mid  ],     nums  [  right  ]}); 
                      ++  mid  ; 
                      while     (  mid     <     right     &&     nums  [  mid  ]     ==     nums  [  mid     -     1  ]) 
                          ++  mid  ; 
                      --  right  ; 
                      while     (  mid     <     right     &&     nums  [  right  ]     ==     nums  [  right     +     1  ]) 
                          --  right  ; 
                  } 
              } 
          } 
          return     res  ; 
      } 
}; 

      class     Solution  : 
    def     threeSum  (  self  ,   nums  :   list  [  int  ])   ->   list  [  list  [  int  ]]: 
        nums  .  sort  () 
        n   =   len  (  nums  ) 
        res   =   [] 

        for   left   in   range  (  n   -   2  ): 
            num   =   nums  [  left  ] 
            if   left   >   0   and   num   ==   nums  [  left   -   1  ]: 
                continue 

            mid  ,   right   =   left   +   1  ,   n   -   1 
            while   mid   <   right  : 
                total   =   num   +   nums  [  mid  ]   +   nums  [  right  ] 
                if   total   <   0  : 
                    mid   +=   1 
                elif   total   >   0  : 
                    right   -=   1 
                else  : 
                    res  .  append  ([  num  ,   nums  [  mid  ],   nums  [  right  ]]) 
                    mid   +=   1 
                    while   mid   <   right   and   nums  [  mid  ]   ==   nums  [  mid   -   1  ]: 
                        mid   +=   1 
                    right   -=   1 
                    while   mid   <   right   and   nums  [  right  ]   ==   nums  [  right   +   1  ]: 
                        right   -=   1 

        return   res 




时间复杂度： \(O(N^2)\)  
空间复杂度： \(O(\log N)\)  <- 排序用的栈

注意到，对于第一个元素 x ，如果它和它后面 最小 的两个元素之和大于0，那么它与之后任意两个元素之和都会大于0；如果 x 和它后面 最大 的两个元素之和小于0，那么它与它之后任意两个元素之和都会小于0。 
  C++  Python        class     Solution     { 
    public  : 
      vector  <  vector  <  int  >>     threeSum  (  vector  <  int  >     &  nums  )     { 
          sort  (  nums  .  begin  (),     nums  .  end  ()); 
          int     n     =     nums  .  size  (); 
          vector  <  vector  <  int  >>     res  ; 
          for     (  int     left     =     0  ;     left     <     n     -     2  ;     ++  left  )     { 
              int     num     =     nums  [  left  ]; 
              if     (  left     >     0     &&     num     ==     nums  [  left     -     1  ]) 
                  continue  ; 
              if     (  num     +     nums  [  left     +     1  ]     +     nums  [  left     +     2  ]     >     0  ) 
                  break  ; 
              if     (  num     +     nums  [  n     -     2  ]     +     nums  [  n     -     1  ]     <     0  ) 
                  continue  ; 
              int     mid     =     left     +     1  ,     right     =     n     -     1  ; 
              while     (  mid     <     right  )     { 
                  int     total     =     num     +     nums  [  mid  ]     +     nums  [  right  ]; 
                  if     (  total     <     0  ) 
                      ++  mid  ; 
                  else     if     (  total     >     0  ) 
                      --  right  ; 
                  else     { 
                      res  .  push_back  ({  num  ,     nums  [  mid  ],     nums  [  right  ]}); 
                      ++  mid  ; 
                      while     (  mid     <     right     &&     nums  [  mid  ]     ==     nums  [  mid     -     1  ]) 
                          ++  mid  ; 
                      --  right  ; 
                      while     (  mid     <     right     &&     nums  [  right  ]     ==     nums  [  right     +     1  ]) 
                          --  right  ; 
                  } 
              } 
          } 
          return     res  ; 
      } 
}; 

      class     Solution  : 
    def     threeSum  (  self  ,   nums  :   list  [  int  ])   ->   list  [  list  [  int  ]]: 
        nums  .  sort  () 
        n   =   len  (  nums  ) 
        res   =   [] 

        for   left   in   range  (  n   -   2  ): 
            num   =   nums  [  left  ] 
            if   left   >   0   and   num   ==   nums  [  left   -   1  ]: 
                continue 
            if   num   +   nums  [  left   +   1  ]   +   nums  [  left   +   2  ]   >   0  : 
                break   # 下一个num只会更大,已经没有其他结果了 
            if   num   +   nums  [  n   -   2  ]   +   nums  [  n   -   1  ]   <   0  : 
                continue   # 现在的num太小了,但是下一个可能够大,所以是continue而不是break 
            mid  ,   right   =   left   +   1  ,   n   -   1 
            while   mid   <   right  : 
                total   =   num   +   nums  [  mid  ]   +   nums  [  right  ] 
                if   total   <   0  : 
                    mid   +=   1 
                elif   total   >   0  : 
                    right   -=   1 
                else  : 
                    res  .  append  ([  num  ,   nums  [  mid  ],   nums  [  right  ]]) 
                    mid   +=   1 
                    while   mid   <   right   and   nums  [  mid  ]   ==   nums  [  mid   -   1  ]: 
                        mid   +=   1 
                    right   -=   1 
                    while   mid   <   right   and   nums  [  right  ]   ==   nums  [  right   +   1  ]: 
                        right   -=   1 

        return   res

  C++  Python        class     Solution     { 
    public  : 
      int     maxArea  (  vector  <  int  >     &  height  )     { 
          int     left     =     0  ,     right     =     (  int  )  height  .  size  ()     -     1  ,     res     =     0  ; 
          while     (  left     <     right  )     { 
              res     =     max  (  res  ,     (  right     -     left  )     *     min  (  height  [  left  ],     height  [  right  ])); 
              if     (  height  [  left  ]     <     height  [  right  ]) 
                  ++  left  ; 
              else 
                  --  right  ; 
          } 
          return     res  ; 
      } 
}; 

