class     Solution  : 
    def     pathSum  (  self  ,   root  :   Optional  [  TreeNode  ],   targetSum  :   int  )   ->   int  : 
        if   not   root  : 
            return   0 

        # 以当前节点为起点的路径数量 
        def     dfs  (  node  ,   tsum  ): 
            if   not   node  : 
                return   0 
            count   =   1   if   node  .  val   ==   tsum   else   0 
            count   +=   dfs  (  node  .  left  ,   tsum   -   node  .  val  ) 
            count   +=   dfs  (  node  .  right  ,   tsum   -   node  .  val  ) 
            return   count 

        # 当前节点为起点 + 左子树起点 + 右子树起点 
        return   dfs  (  root  ,   targetSum  )   +   self  .  pathSum  (  root  .  left  ,   targetSum  )   +   self  .  pathSum  (  root  .  right  ,   targetSum  ) 




时间复杂度： \(O(N^2)\) ，每个节点都要做一次DFS，每次DFS都是 \(O(N)\)  
空间复杂度： \(O(N)\) ，栈开销

因为路径方向必须是向下的，我们其实可以把树的分叉看成多条不同的链，那么这个问题就简化为在这些链上去找一个区间和为 targetSum 的数目。看到求区间和，要想到前缀和数组。下面的代码相当于  560.和为 K 的子数组[中等]  的一次遍历写法的二叉树版本。使用哈希表缓存前缀和，可以避免遍历前缀和数组来两两匹配找区间和。 
  C++  Python        class     Solution     { 
    public  : 
      int     pathSum  (  TreeNode     *  root  ,     int     targetSum  )     { 
          unordered_map  <  long     long  ,     int  >     prefix  {{  0  ,     1  }}; 
          auto     dfs     =     [  &  ](  auto     &&  self  ,     TreeNode     *  node  ,     long     long     curr  )     ->     int     { 
              if     (  !  node  ) 
                  return     0  ; 
              curr     +=     node  ->  val  ; 
              int     ret     =     prefix  [  curr     -     targetSum  ]; 
              ++  prefix  [  curr  ]; 
              ret     +=     self  (  self  ,     node  ->  left  ,     curr  )     +     self  (  self  ,     node  ->  right  ,     curr  ); 
              --  prefix  [  curr  ];     // 离开当前路径时撤销，避免影响兄弟分支。 
              return     ret  ; 
          }; 
          return     dfs  (  dfs  ,     root  ,     0  ); 
      } 
}; 

