    def     pathSum  (  self  ,   root  :   TreeNode  ,   targetSum  :   int  )   ->   int  : 
        prefix   =   collections  .  defaultdict  (  int  ) 
        prefix  [  0  ]   =   1 

        def     dfs  (  root  ,   curr  ): 
            if   not   root  : 
                return   0 

            ret   =   0 
            curr   +=   root  .  val 
            ret   +=   prefix  [  curr   -   targetSum  ]   # 后 - 前 = targetSum 
            prefix  [  curr  ]   +=   1 
            ret   +=   dfs  (  root  .  left  ,   curr  ) 
            ret   +=   dfs  (  root  .  right  ,   curr  ) 
            prefix  [  curr  ]   -=   1   # 回溯 

            return   ret 

        return   dfs  (  root  ,   0  ) 




