  C++  Python        #include     <iostream> 
#include     <vector> 
#include     <queue> 
using     namespace     std  ; 

// 二叉树节点定义 
struct     TreeNode     { 
      int     val  ; 
      TreeNode  *     left  ; 
      TreeNode  *     right  ; 
      TreeNode  (  int     x  )     :     val  (  x  ),     left  (  nullptr  ),     right  (  nullptr  )     {} 
}; 

// 构造二叉树的函数 
TreeNode  *     buildTree  (  const     vector  <  int  *>&     arr  )     { 
      if     (  arr  .  empty  ()     ||     arr  [  0  ]     ==     nullptr  )     return     nullptr  ; 

      TreeNode  *     root     =     new     TreeNode  (  *  arr  [  0  ]); 
      queue  <  TreeNode  *>     q  ; 
      q  .  push  (  root  ); 

      int     i     =     1  ; 
      while     (  !  q  .  empty  ()     &&     i     <     arr  .  size  ())     { 
          TreeNode  *     node     =     q  .  front  (); 
          q  .  pop  (); 

          // 左孩子 
          if     (  arr  [  i  ]     !=     nullptr  )     { 
              node  ->  left     =     new     TreeNode  (  *  arr  [  i  ]);     // 一定是先在父节点构造子节点 
              q  .  push  (  node  ->  left  ); 
          } 
          i  ++  ; 

          // 右孩子 
          if     (  i     <     arr  .  size  ()     &&     arr  [  i  ]     !=     nullptr  )     { 
              node  ->  right     =     new     TreeNode  (  *  arr  [  i  ]); 
              q  .  push  (  node  ->  right  ); 
          } 
          i  ++  ; 
      } 
      return     root  ; 
} 

// 打印二叉树（层序遍历） 
void     printTree  (  TreeNode  *     root  )     { 
      if     (  !  root  )     return  ; 
      queue  <  TreeNode  *>     q  ; 
      q  .  push  (  root  ); 
      while     (  !  q  .  empty  ())     { 
          int     size     =     q  .  size  (); 
          for     (  int     i     =     0  ;     i     <     size  ;     i  ++  )     { 
              TreeNode  *     node     =     q  .  front  (); 
              q  .  pop  (); 
              if     (  node  )     { 
                  q  .  push  (  node  ->  left  ); 
                  q  .  push  (  node  ->  right  ); 
                  cout     <<     node  ->  val     <<     " "  ; 
              } 
              else     { 
                  cout     <<     "null "  ; 
              } 
          } 
          cout     <<     endl  ; 
      } 
} 

int     main  ()     { 
      // 用 int* 指针来表示 null 
      int     a     =     1  ,     b     =     3  ; 
      vector  <  int  *>     arr     =     {  &  a  ,     &  b  ,     nullptr  }; 

      TreeNode  *     root     =     buildTree  (  arr  ); 
      printTree  (  root  ); 
      // 1 
      // 3 null 
} 

