class     TreeNode  : 
    def     __init__  (  self  ,   val  ,   left  =  None  ,   right  =  None  ): 
        self  .  val  ,   self  .  left  ,   self  .  right   =   val  ,   left  ,   right 

def     buildTree  (  arr  ): 
    if   not   arr   or   arr  [  0  ]   is   None  :   return   None 
    root   =   TreeNode  (  arr  [  0  ]) 
    queue   =   deque  ([  root  ]) 
    i   =   1 
