        if   j   <   w  [  i  ]:   return   dfs  (  i   -   1  ,   j  ) 
        return   max  (  dfs  (  i   -   1  ,   j  ),   dfs  (  i   -   1  ,   j   -   w  [  i  ])   +   v  [  i  ]) 
