def     zero_one_knapsack  (  c  :   int  ,   w  :   List  [  int  ],   v  :   List  [  int  ])   ->   int  : 
    n   =   len  (  w  ) 
    dp   =   [  0  ]   *   (  c   +   1  )   # int[c+1] 
    for   i   in   range  (  n  ):   # 遍历物品 
        for   j   in   range  (  c  ,   w  [  i  ]   -   1  ,   -  1  ):   # 遍历背包容量(倒序遍历!) 
