    dp   =   [  0  ]   *   (  c   +   1  )   # int[c+1] 
    for   i   in   range  (  n  ):   # 遍历物品 
        for   j   in   range  (  w  [  i  ],   c   +   1  ):   # 遍历背包容量(正序遍历!) 
            dp  [  j  ]   =   max  (  dp  [  j  ],   dp  [  j   -   w  [  i  ]]   +   v  [  i  ]) 
    return   dp  [  c  ]

