          vector  <  vector  <  int  >>     res  ; 
          vector  <  int  >     path  (  n  ); 
          auto     dfs     =     [  &  ](  auto     &&  self  ,     int     i  ,     unordered_set  <  int  >     remaining  )     ->     void     { 
