                  next  .  erase  (  x  ); 
                  self  (  self  ,     i     +     1  ,     std  ::  move  (  next  )); 
              } 
          }; 
          dfs  (  dfs  ,     0  ,     unordered_set  <  int  >  (  nums  .  begin  (),     nums  .  end  ())); 
          return     res  ; 
      } 
}; 

