  C++  Python        class     Solution     { 
    public  : 
      vector  <  vector  <  int  >>     permute  (  vector  <  int  >     &  nums  )     { 
          int     n     =     nums  .  size  (); 
          vector  <  vector  <  int  >>     res  ; 
          auto     dfs     =     [  &  ](  auto     &&  self  ,     int     i  )     ->     void     { 
              if     (  i     ==     n  )     { 
                  res  .  push_back  (  nums  ); 
                  return  ; 
              } 
              for     (  int     j     =     i  ;     j     <     n  ;     ++  j  )     { 
                  swap  (  nums  [  i  ],     nums  [  j  ]); 
                  self  (  self  ,     i     +     1  ); 
                  swap  (  nums  [  i  ],     nums  [  j  ]); 
              } 
          }; 
          dfs  (  dfs  ,     0  ); 
          return     res  ; 
      } 
}; 

