class     MedianFinder  : 
    def     __init__  (  self  ): 
        self  .  nums   =   [] 

    def     addNum  (  self  ,   num  ): 
        # 标准库有序列表版本：插入 O(N)，C++ multiset 版本插入 O(log N)。 
        insort  (  self  .  nums  ,   num  ) 

    def     findMedian  (  self  ): 
        n   =   len  (  self  .  nums  ) 
        return   (  self  .  nums  [(  n   -   1  )   //   2  ]   +   self  .  nums  [  n   //   2  ])   /   2 




