          vector  <  int  >     res  (  n  ),     st  ; 
          for     (  int     i     =     0  ;     i     <     n  ;     ++  i  )     { 
              while     (  !  st  .  empty  ()     &&     temperatures  [  i  ]     >     temperatures  [  st  .  back  ()])     { 
                  int     j     =     st  .  back  (); 
                  st  .  pop_back  (); 
                  res  [  j  ]     =     i     -     j  ; 
              } 
              st  .  push_back  (  i  ); 
          } 
          return     res  ; 
      } 
}; 

