        left  ,   right   =   [  -  1  ]   *   n  ,   [  n  ]   *   n 
        mono_stack   =   []   # 单调递增队列 
        for   i   in   range  (  n  ): 
            while   mono_stack   and   heights  [  i  ]   <   heights  [  mono_stack  [  -  1  ]]: 
                prev   =   mono_stack  .  pop  () 
                right  [  prev  ]   =   i 
            mono_stack  .  append  (  i  ) 
        mono_stack  .  clear  () 
        for   i   in   range  (  n   -   1  ,   -  1  ,   -  1  ): 
            while   mono_stack   and   heights  [  i  ]   <   heights  [  mono_stack  [  -  1  ]]: 
                prev   =   mono_stack  .  pop  () 
                left  [  prev  ]   =   i 
            mono_stack  .  append  (  i  ) 

        res   =   0 
        for   i  ,   height   in   enumerate  (  heights  ): 
            res   =   max  (  res  ,   (  right  [  i  ]   -   left  [  i  ]   -   1  )   *   height  ) 
        return   res 




